    assertTrue(isGreaterThan(exchange.milliseconds(), 0), std::string("go transpiler workaround"));
    // @SKIP_START_GO
    std::any bids = ccxt::list{ccxt::list{789.1, 111.05}, ccxt::list{789.1, 111.05}, ccxt::list{123.3, 456.2}, ccxt::list{784.2, 111.05}, ccxt::list{789.1, 111.05}};
    std::any expectedBids = ccxt::list{ccxt::list{123.3, 456.2}, ccxt::list{784.2, 111.05}, ccxt::list{789.1, 333.15}};
    assertDeepEqual(exchange, std::any{}, std::string("aggregate"), exchange.aggregate(exchange.sortBy(bids, 0)), expectedBids);
    std::any asks = ccxt::list{ccxt::list{123.2, 456.2}, ccxt::list{784.2, 222.44}, ccxt::list{789.1, 111.01}};
    std::any expectedAsks = ccxt::list{ccxt::list{123.2, 456.2}, ccxt::list{784.2, 222.44}, ccxt::list{789.1, 111.01}};
    assertDeepEqual(exchange, std::any{}, std::string("aggregate"), exchange.aggregate(exchange.sortBy(asks, 0)), expectedAsks);
    assertDeepEqual(exchange, std::any{}, std::string("aggregate"), exchange.aggregate(ccxt::list{}), ccxt::list{});
    // Test 1: Simple aggregation - same price combined
    std::any result1 = exchange.aggregate(ccxt::list{ccxt::list{100.2, 1.01}, ccxt::list{101.5, 2.01}, ccxt::list{100.2, 0.5}});
    assertDeepEqual(exchange, std::any{}, std::string("testAggregate"), result1, ccxt::list{ccxt::list{100.2, 1.51}, ccxt::list{101.5, 2.01}});
    // Test 2: With extra fields (should be ignored)
    std::any result2 = exchange.aggregate(ccxt::list{ccxt::list{100.2, 1.01, std::string("extra")}, ccxt::list{101.5, 2.01, std::string("data"), std::string("more")}});
    assertDeepEqual(exchange, std::any{}, std::string("testAggregate"), result2, ccxt::list{ccxt::list{100.2, 1.01}, ccxt::list{101.5, 2.01}});
