    std::any result3 = exchange.aggregate(ccxt::list{ccxt::list{100.2, 1.01}, ccxt::list{101.5, 0}, ccxt::list{102.4, 2.01}});
    assertDeepEqual(exchange, std::any{}, std::string("testAggregate"), result3, ccxt::list{ccxt::list{100.2, 1.01}, ccxt::list{102.4, 2.01}});
