    std::any result6 = exchange.aggregate(ccxt::list{ccxt::list{100.2, 0.12}, ccxt::list{100.2, 0.2}, ccxt::list{100.2, 0.3}, ccxt::list{100.2, 0.4}});
    assertDeepEqual(exchange, std::any{}, std::string("testAggregate"), result6, ccxt::list{ccxt::list{100.2, 1.02}});
