    std::any result10 = exchange.aggregate(ccxt::list{ccxt::list{100.2, 1.04}, ccxt::list{100.2, 0}, ccxt::list{100.2, 2.04}});
    assertDeepEqual(exchange, std::any{}, std::string("testAggregate"), result10, ccxt::list{ccxt::list{100.2, 3.08}});
